parameters.jsCode:
const webhook = $('Webhook - create-and-pair').first().json.body;
const existing = $('Postgres - lookup connection').first().json;
let sessionId = existing?.wasender_session_id;
let connection = existing;

try {
  const upsert = $('Postgres - upsert after create').first()?.json;
  if (upsert?.wasender_session_id) {
    sessionId = upsert.wasender_session_id;
    connection = upsert;
  }
} catch (_) {}

if (!sessionId) {
  return [{ json: { error: true, message: 'Could not resolve wasender_session_id', owner_email: webhook.owner_email, phone_number: webhook.phone_number } }];
}

return [{ json: { ...webhook, wasender_session_id: sessionId, connection_id: connection?.id ?? null, connection } }];

const session = $('Wasender - get session status (pair)').first().json;
const connection = $('Postgres - mark connected').first().json;
return [{ json: { success: true, already_connected: true, status: 'connected', wasender_session_id: connection.wasender_session_id, connection, wasender: session } }];

const qr = $('Wasender - qrcode (pair)').first().json;
const data = qr.data ?? qr;
const qrString = data.qrCode ?? data.qr_code ?? qr.qrCode ?? qr.qr_code ?? null;
const wasenderStatus = String(data.status ?? qr.status ?? 'need_scan').toLowerCase();
const connection = $('Postgres - mark pending').first().json;
const sessionId = $('Code - resolve session id').first().json.wasender_session_id;
return [{ json: {
  success: true,
  already_connected: false,
  status: wasenderStatus === 'connected' ? 'connected' : 'pending',
  wasender_status: wasenderStatus,
  wasender_session_id: sessionId,
  qr_code: qrString,
  qrCode: qrString,
  expires_in: 30,
  connection,
  wasender: qr,
  message: qrString ? 'Scan the QR code with WhatsApp within 30 seconds.' : 'QR code unavailable. Refresh and try again.'
} }];

const wasender = $('Wasender - poll session status').first().json;
const connection = $('Postgres - sync poll status').first().json;
const status = String(wasender.data?.status || wasender.status || connection.status || 'disconnected').toLowerCase();
return [{ json: { success: true, status, connected: status === 'connected', connection, wasender } }];

